 * @param  string  $column
 * @return $this
 */
public function loadAvg($relations, $column)
{
    return $this->loadAggregate($relations, $column, 'avg');
}

/**
 * Load a set of related existences onto the collection.
 *
 * @param  array<array-key, (callable(\Illuminate\Database\Eloquent\Builder<TModel>): mixed)|string>|string  $relations
 * @return $this
 */
public function loadExists($relations)
{
    return $this->loadAggregate($relations, '*', 'exists');
}

/**
 * Apply the inverse relation from the given relationship to all models in the collection.
 *
 * @param  \Illuminate\Database\Eloquent\Relations\Relation  $relation
 * @param  \Illuminate\Database\Eloquent\Model|null  $parent
 * @return $this
 */
public function applyInverseRelationToCollection(Relation $relation, ?Model $parent = null)
{
    $parent ??= $relation->getParent();
    $inverse = $relation->getInverseRelationship();
    $builderModel = $relation->getQuery()->getModel();

    $parentIdentity = implode("\0", [
        (string) $parent->getConnectionName(),
        $parent->getTable(),
        $parent->getKeyName(),
        $parent->exists ? '1' : '0',
        $builderModel->getTable(),
        (string) $inverse,
    ]);

    $parentsByIdentity = [$parentIdentity => $parent];
    $boundParent = $parentsByIdentity[$parentIdentity] ?? $parent;

    foreach ($this->items as $model) {
        if ($inverse) {
            $model->setRelation($inverse, $boundParent);
        }
    }

    return $this;
}

/**
 * Match the eagerly loaded results to their many parents.
 *
 * @param  array<int, TDeclaringModel>  $models
 * @param  \Illuminate\Database\Eloquent\Collection<int, TRelatedModel>  $results
 * @param  string  $relation
 * @param  string  $type
 * @return array<int, TDeclaringModel>
 */
protected function matchOneOrMany(array $models, Collection $results, $relation, $type)
{
    $dictionary = $this->buildDictionary($results);

    // Once we have the dictionary we can simply spin through the parent models to
    // link them up with their children using the keyed dictionary to make the
    // matching very convenient and easy work. Then we'll just return them.
    foreach ($models as $model) {
        if (isset($dictionary[$key = $this->getDictionaryKey($model->getAttribute($this->localKey))])) {
            $related = $this->getRelationValue($dictionary, $key, $type);
            $model->setRelation($relation, $related);

